css:
* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: #151413;
  background: #ffffff;
  overflow-x: hidden;
}
button, input, select { font: inherit; }
a { color: inherit; text-decoration: none; }

/* Announcement Bar */
.top-announcement-bar {
  background: #0e0e0e;
  color: #ffffff;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  padding: 0 40px;
  height: 36px;
  display: flex;
  align-items: center;
}
.top-bar-inner {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.bar-sep { opacity: 0.4; margin: 0 10px; }

/* Navigation Header */
.gazu-header {
  background: #ffffff;
  border-bottom: 1px solid #ebebeb;
  position: sticky;
  top: 0;
  z-index: 99;
  height: 70px;
}
.gazu-nav {
  max-width: 1440px;
  margin: 0 auto;
  height: 100%;
  padding: 0 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.gazu-nav-left {
  display: flex;
  gap: 28px;
}
.gazu-nav-left a {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #555555;
  transition: color 0.2s;
}
.gazu-nav-left a:hover,
.gazu-nav-left a.is-active {
  color: #151413;
}
.gazu-brand a {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: 0.22em;
  color: #151413;
}
.gazu-nav-right {
  display: flex;
  align-items: center;
  gap: 20px;
}
.gazu-action-btn {
  background: none;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #151413;
  padding: 8px 16px;
  border-radius: 999px;
  border: 1px solid #e0e0e0;
  transition: all 0.2s;
}
.gazu-action-btn:hover {
  background: #151413;
  color: #ffffff;
  border-color: #151413;
}

/* Category Hero */
.col-hero {
  background: #fbfbf9;
  border-bottom: 1px solid #ebebeb;
  padding: 60px 40px 48px;
}
.col-hero-inner {
  max-width: 1440px;
  margin: 0 auto;
}
.col-breadcrumb {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: #888888;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.col-breadcrumb a:hover {
  color: #151413;
}
.col-title {
  font-size: 44px;
  font-weight: 900;
  letter-spacing: -0.03em;
  color: #151413;
  margin: 0 0 16px;
}
.col-desc {
  font-size: 15px;
  line-height: 1.6;
  color: #666666;
  max-width: 680px;
  margin: 0 0 28px;
}
.col-meta-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 20px;
  border-top: 1px solid #e8e8e8;
}
.col-count {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #151413;
}
.col-back-link {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #151413;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: transform 0.2s;
}
.col-back-link:hover {
  transform: translateX(-4px);
}

/* Toolbar: Filters & Sorting */
.col-toolbar {
  max-width: 1440px;
  margin: 32px auto 0;
  padding: 0 40px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.col-filter-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.col-filter-btn {
  background: #f4f4f4;
  border: 1px solid transparent;
  padding: 8px 18px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #666666;
  cursor: pointer;
  transition: all 0.2s;
}
.col-filter-btn:hover {
  color: #151413;
  background: #ececec;
}
.col-filter-btn.is-active {
  background: #151413;
  color: #ffffff;
  border-color: #151413;
}
.col-sort-box {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #666666;
}
.col-sort-select {
  border: 1px solid #d4d4d4;
  border-radius: 999px;
  padding: 8px 20px 8px 14px;
  background: #ffffff;
  font-size: 12px;
  font-weight: 700;
  color: #151413;
  cursor: pointer;
  outline: none;
}

/* Product Grid */
.col-grid-section {
  max-width: 1440px;
  margin: 32px auto 80px;
  padding: 0 40px;
}
.col-product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px 24px;
}
@media (max-width: 1200px) {
  .col-product-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 820px) {
  .col-product-grid { grid-template-columns: repeat(2, 1fr); gap: 20px 14px; }
  .col-grid-section, .col-toolbar, .col-hero, .gazu-nav { padding-left: 20px; padding-right: 20px; }
}
@media (max-width: 520px) {
  .col-product-grid { grid-template-columns: 1fr; }
}

/* Product Card (Clean Front View Only) */
.col-product-card {
  background: #ffffff;
  border: 1px solid #ececec;
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.col-product-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.08);
  border-color: #d8d8d8;
}

.col-product-media {
  position: relative;
  background: #f8f8f6;
  width: 100%;
  height: 380px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px 16px;
  overflow: hidden;
}
.col-product-media img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  filter: drop-shadow(0 10px 18px rgba(0,0,0,0.1));
}
.col-product-card:hover .col-product-media img {
  transform: scale(1.04);
}
.col-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: #ffffff;
  color: #151413;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid #ebebeb;
  box-shadow: 0 2px 6px rgba(0,0,0,0.04);
  z-index: 2;
}
.col-quick-actions {
  position: absolute;
  bottom: 14px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  opacity: 0;
  transform: translateY(8px);
  transition: all 0.25s ease;
  z-index: 3;
}
.col-product-card:hover .col-quick-actions {
  opacity: 1;
  transform: translateY(0);
}
.col-quick-btn {
  background: rgba(21, 20, 19, 0.92);
  color: #ffffff;
  border: none;
  border-radius: 999px;
  padding: 10px 22px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  cursor: pointer;
  backdrop-filter: blur(4px);
  box-shadow: 0 6px 16px rgba(0,0,0,0.2);
  transition: background 0.2s;
}
.col-quick-btn:hover {
  background: #000000;
}

.col-product-info {
  padding: 20px 20px 22px;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.col-product-cat {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: #999999;
  margin-bottom: 6px;
  text-transform: uppercase;
}
.col-product-title {
  font-size: 15px;
  font-weight: 800;
  color: #151413;
  margin: 0 0 10px;
  line-height: 1.35;
  min-height: 40px;
}
.col-product-price {
  font-size: 16px;
  font-weight: 900;
  color: #151413;
  margin-bottom: 16px;
}
.col-sizes {
  display: flex;
  gap: 6px;
  margin-bottom: 18px;
}
.col-size-pill {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid #d4d4d4;
  background: #ffffff;
  color: #151413;
  font-size: 11px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}
.col-size-pill:hover {
  border-color: #151413;
}
.col-size-pill.is-active {
  background: #151413;
  color: #ffffff;
  border-color: #151413;
}
.col-add-btn {
  margin-top: auto;
  background: #151413;
  color: #ffffff;
  border: none;
  padding: 13px 20px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
}
.col-add-btn:hover {
  background: #333333;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0,0,0,0.15);
}

/* Quick View Dialog Modal (Front View Only) */
.qv-dialog {
  border: none;
  border-radius: 16px;
  padding: 0;
  background: #ffffff;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.25);
  max-width: 860px;
  width: 90%;
  overflow: hidden;
}
.qv-dialog::backdrop {
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(6px);
}
.qv-inner {
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  position: relative;
}
@media (max-width: 768px) {
  .qv-inner { grid-template-columns: 1fr; }
}
.qv-close {
  position: absolute;
  top: 14px;
  right: 14px;
  background: #f4f4f4;
  border: none;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background 0.2s;
}
.qv-close:hover { background: #e0e0e0; }
.qv-media {
  background: #f8f8f6;
  padding: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.qv-media img {
  max-width: 100%;
  max-height: 440px;
  object-fit: contain;
  filter: drop-shadow(0 14px 24px rgba(0,0,0,0.12));
}
.qv-details {
  padding: 40px 36px;
  display: flex;
  flex-direction: column;
}
.qv-cat {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: #999999;
  margin-bottom: 8px;
}
.qv-title {
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: #151413;
  margin: 0 0 12px;
  line-height: 1.25;
}
.qv-price {
  font-size: 22px;
  font-weight: 900;
  color: #151413;
  margin-bottom: 18px;
}
.qv-desc {
  font-size: 14px;
  line-height: 1.6;
  color: #666666;
  margin: 0 0 20px;
}
.qv-details-list {
  list-style: none;
  padding: 0;
  margin: 0 0 24px;
}
.qv-details-list li {
  font-size: 12px;
  font-weight: 600;
  color: #555555;
  padding: 4px 0 4px 18px;
  position: relative;
}
.qv-details-list li::before {
  content: '✓';
  position: absolute;
  left: 0;
  color: #151413;
  font-weight: 800;
}
.qv-sizes {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}
.qv-size-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid #d4d4d4;
  background: #ffffff;
  color: #151413;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.2s;
}
.qv-size-btn.is-active {
  background: #151413;
  color: #ffffff;
  border-color: #151413;
}
.qv-add-btn {
  background: #151413;
  color: #ffffff;
  border: none;
  padding: 16px 28px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  transition: all 0.2s;
}
.qv-add-btn:hover {
  background: #333333;
  transform: translateY(-2px);
}

/* Bag Cart Dialog Modal */
.bag-dialog {
  border: none;
  border-radius: 16px;
  padding: 32px;
  background: #ffffff;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.25);
  max-width: 520px;
  width: 90%;
}
.bag-dialog::backdrop {
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(6px);
}
.bag-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #eee;
  padding-bottom: 18px;
  margin-bottom: 20px;
}
.bag-head h3 { margin: 0; font-size: 20px; font-weight: 900; }
.bag-items-list {
  max-height: 380px;
  overflow-y: auto;
  margin-bottom: 20px;
}
.bag-item-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 0;
  border-bottom: 1px solid #f4f4f4;
}
.bag-item-img {
  width: 60px;
  height: 60px;
  object-fit: contain;
  background: #f8f8f6;
  border-radius: 8px;
  padding: 4px;
}
.bag-item-meta { flex: 1; }
.bag-item-name { font-size: 13px; font-weight: 800; color: #151413; margin: 0 0 4px; }
.bag-item-price { font-size: 12px; color: #666; font-weight: 600; }
.bag-item-del {
  background: none; border: none; color: #999; cursor: pointer; font-size: 18px;
}
.bag-item-del:hover { color: #e53935; }
.bag-total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 16px;
  font-weight: 900;
  padding: 16px 0;
  border-top: 2px solid #151413;
}
.bag-checkout-btn {
  width: 100%;
  background: #151413;
  color: #ffffff;
  border: none;
  padding: 16px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  cursor: pointer;
  transition: background 0.2s;
}
.bag-checkout-btn:hover { background: #333333; }

/* Toast Notification */
.toast-status {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: #151413;
  color: #ffffff;
  padding: 14px 24px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  box-shadow: 0 10px 24px rgba(0,0,0,0.25);
  z-index: 9999;
  opacity: 0;
  transform: translateY(12px);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: none;
}
.toast-status.is-on {
  opacity: 1;
  transform: translateY(0);
}

