    const activePill = card.querySelector('.col-size-pill.is-active');
    const size = activePill ? activePill.dataset.size : 'M';

    const bag = getBag();
    const existing = bag.items.find(x => x.id === pid && x.size === size);
    if (existing) {
      existing.quantity = (existing.quantity || 1) + 1;
