// Cart Dialog Open / Close & Rendering
const bagDialog = document.getElementById('bag-dialog');
const bagContainer = document.getElementById('bag-items-container');
const bagSubtotal = document.getElementById('bag-subtotal');

window.openBagDialog = function() {
  const b = getBag();
  bagContainer.innerHTML = '';
  if (!b.items.length) {
    bagContainer.innerHTML = '<p style="text-align:center; padding:30px 0; color:#888;">Your styling bag is currently empty.</p>';
    bagSubtotal.textContent = '$0.00';
  } else {
    let total = 0;
    b.items.forEach((it, idx) => {
      const p = it.priceNum || parseFloat((it.price || '0').replace(/[^0-9.]/g, '')) || 0;
      const q = it.quantity || 1;
      total += p * q;

      const row = document.createElement('div');
      row.className = 'bag-item-row';
      row.innerHTML = `
        <img src="${it.image}" class="bag-item-img" alt="">
        <div class="bag-item-meta">
          <h5 class="bag-item-name">${it.name}</h5>
          <div class="bag-item-price">${it.price} · Size: ${it.size || 'M'} (Qty: ${q})</div>
        </div>
        <button type="button" class="bag-item-del" data-del-idx="${idx}" aria-label="Remove item">&times;</button>
      `;
      bagContainer.appendChild(row);
    });
    bagSubtotal.textContent = '$' + total.toFixed(2);

    bagContainer.querySelectorAll('[data-del-idx]').forEach(btn => {
      btn.addEventListener('click', () => {
        const i = parseInt(btn.dataset.delIdx, 10);
        b.items.splice(i, 1);
        saveBag(b);
        openBagDialog();
      });
    });
  }
  bagDialog.showModal();
};

window.closeBagDialog = function() {
  bagDialog.close();
};

bagDialog.addEventListener('click', (e) => {
  if (e.target === bagDialog) bagDialog.close();
});

